<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Cooking Mode – Lemon Garlic Pasta</title>
<style>
:root{--bg:#1c1a17;--panel:#27241f;--ink:#f5efe4;--mute:#a89f90;--acc:#f0a03c;--ok:#7cc47f;--line:#3a352d}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:var(--bg);color:var(--ink);height:100vh;overflow:hidden;display:flex;flex-direction:column;-webkit-tap-highlight-color:transparent;user-select:none}
header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;border-bottom:1px solid var(--line)}
header h1{font-size:22px;font-weight:600}
header small{color:var(--mute);font-size:15px;display:block;margin-top:2px}
.tabs{display:flex;gap:8px}
.tab{background:var(--panel);border:1px solid var(--line);color:var(--ink);font-size:17px;padding:12px 20px;border-radius:14px;cursor:pointer}
.tab.on{background:var(--acc);color:#1c1a17;border-color:var(--acc);font-weight:700}
main{flex:1;position:relative;overflow:hidden}
section{position:absolute;inset:0;padding:28px;display:none;flex-direction:column}
section.on{display:flex}
.progress{display:flex;gap:6px;margin-bottom:24px}
.progress i{flex:1;height:8px;border-radius:4px;background:var(--line)}
.progress i.done{background:var(--acc)}
.stepno{color:var(--acc);font-size:20px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.steptext{font-size:44px;line-height:1.25;font-weight:500;margin:18px 0;flex:1;overflow:auto}
.steptext b{color:var(--acc)}
.timerbtn{align-self:flex-start;background:transparent;border:2px solid var(--acc);color:var(--acc);font-size:24px;padding:16px 28px;border-radius:18px;cursor:pointer;margin-bottom:20px}
.nav{display:flex;gap:16px}
.nav button{flex:1;font-size:26px;font-weight:700;padding:28px;border-radius:22px;border:none;cursor:pointer}
.prev{background:var(--panel);color:var(--ink)}
.next{background:var(--acc);color:#1c1a17;flex:2!important}
.nav button:disabled{opacity:.3}
.hint{color:var(--mute);text-align:center;margin-top:14px;font-size:15px}
ul{list-style:none;overflow:auto;flex:1}
li{display:flex;align-items:center;gap:20px;padding:20px 8px;border-bottom:1px solid var(--line);font-size:26px;cursor:pointer}
li .box{width:44px;height:44px;border-radius:12px;border:3px solid var(--mute);flex-shrink:0;display:grid;place-items:center;font-size:28px;color:#1c1a17}
li.chk .box{background:var(--ok);border-color:var(--ok)}
li.chk span.t{text-decoration:line-through;color:var(--mute)}
li .q{margin-left:auto;color:var(--acc);font-weight:600}
.ingtop{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;font-size:18px;color:var(--mute)}
#timers{display:flex;gap:12px;padding:0 28px 18px;flex-wrap:wrap}
.tm{background:var(--panel);border:2px solid var(--line);border-radius:18px;padding:12px 18px;display:flex;align-items:center;gap:14px;font-size:20px}
.tm .c{font-size:32px;font-variant-numeric:tabular-nums;font-weight:700}
.tm button{background:var(--line);border:none;color:var(--ink);font-size:18px;padding:10px 14px;border-radius:12px;cursor:pointer}
.tm.ring{border-color:var(--acc);animation:p 1s infinite}
@keyframes p{50%{background:#5a3a12}}
.mic{background:var(--panel);border:1px solid var(--line);color:var(--mute);font-size:15px;padding:10px 14px;border-radius:12px;cursor:pointer;margin-right:10px}
.mic.on{color:var(--ok);border-color:var(--ok)}
</style>
</head>
<body>
<header>
  <div><h1>Lemon Garlic Pasta</h1><small>Serves 4 · 25 min</small></div>
  <div style="display:flex;align-items:center">
    <button class="mic" id="mic">🎤 Voice off</button>
    <div class="tabs">
      <button class="tab on" data-v="steps">Steps</button>
      <button class="tab" data-v="ing">Ingredients</button>
    </div>
  </div>
</header>
<div id="timers"></div>
<main>
  <section id="steps" class="on">
    <div class="progress" id="prog"></div>
    <div class="stepno" id="no"></div>
    <div class="steptext" id="txt"></div>
    <button class="timerbtn" id="tbtn"></button>
    <div class="nav">
      <button class="prev" id="prev">← Back</button>
      <button class="next" id="next">Next →</button>
    </div>
    <div class="hint">Tap anywhere on the step text, swipe, or say “next” / “back” / “start timer”</div>
  </section>
  <section id="ing">
    <div class="ingtop"><span id="cnt"></span><button class="tab" id="reset">Reset</button></div>
    <ul id="list"></ul>
  </section>
</main>
<script>
const ING=[["Spaghetti","400 g"],["Garlic cloves, sliced","5"],["Lemon, zest & juice","1"],["Olive oil","4 tbsp"],["Butter","2 tbsp"],["Parmesan, grated","60 g"],["Red pepper flakes","½ tsp"],["Fresh parsley","1 handful"],["Salt & pepper","to taste"]];
const STEPS=[
 {t:"Bring a large pot of <b>salted water</b> to a rolling boil.",m:8},
 {t:"Add the <b>spaghetti</b> and cook until al dente, stirring now and then.",m:10},
 {t:"Meanwhile, warm <b>olive oil</b> and <b>butter</b> in a wide pan over medium-low heat."},
 {t:"Add <b>garlic</b> and <b>pepper flakes</b>. Cook gently until golden — don't let it burn.",m:2},
 {t:"Reserve <b>1 cup pasta water</b>, then drain the spaghetti."},
 {t:"Toss pasta in the pan with <b>lemon zest, juice</b> and a splash of pasta water."},
 {t:"Add <b>parmesan</b> and toss until glossy. Finish with <b>parsley</b>, salt & pepper. Enjoy!"}];
let cur=+localStorage.ck_step||0,checked=JSON.parse(localStorage.ck_ing||"[]"),timers=[],tid=0;
const $=id=>document.getElementById(id);
function render(){
  const s=STEPS[cur];
  $("prog").innerHTML=STEPS.map((_,i)=>`<i class="${i<=cur?'done':''}"></i>`).join("");
  $("no").textContent=`Step ${cur+1} of ${STEPS.length}`;
  $("txt").innerHTML=s.t;
  $("tbtn").style.display=s.m?"":"none";
  if(s.m)$("tbtn").textContent=`⏱ Start ${s.m} min timer`;
  $("prev").disabled=cur==0;
  $("next").textContent=cur==STEPS.length-1?"Done ✓":"Next →";
  localStorage.ck_step=cur;
}
function go(d){cur=Math.max(0,Math.min(STEPS.length-1,cur+d));render()}
$("prev").onclick=()=>go(-1);$("next").onclick=()=>go(1);$("txt").onclick=()=>go(1);
let sx=0;$("steps").addEventListener("touchstart",e=>sx=e.touches[0].clientX);
$("steps").addEventListener("touchend",e=>{const dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>70)go(dx<0?1:-1)});
function renderIng(){
  $("list").innerHTML=ING.map((g,i)=>`<li data-i="${i}" class="${checked.includes(i)?'chk':''}"><div class="box">${checked.includes(i)?'✓':''}</div><span class="t">${g[0]}</span><span class="q">${g[1]}</span></li>`).join("");
  $("cnt").textContent=`${checked.length} of ${ING.length} ready`;
  localStorage.ck_ing=JSON.stringify(checked);
}
$("list").onclick=e=>{const li=e.target.closest("li");if(!li)return;const i=+li.dataset.i;checked=checked.includes(i)?checked.filter(x=>x!=i):[...checked,i];renderIng()};
$("reset").onclick=()=>{checked=[];renderIng()};
document.querySelectorAll(".tabs .tab").forEach(b=>b.onclick=()=>{
  document.querySelectorAll(".tabs .tab").forEach(x=>x.classList.toggle("on",x==b));
  document.querySelectorAll("section").forEach(s=>s.classList.toggle("on",s.id==b.dataset.v));
});
let actx;
function beep(){try{actx=actx||new AudioContext();const o=actx.createOscillator(),g=actx.createGain();o.frequency.value=880;o.connect(g);g.connect(actx.destination);g.gain.setValueAtTime(.3,actx.currentTime);g.gain.exponentialRampToValueAtTime(.001,actx.currentTime+.5);o.start();o.stop(actx.currentTime+.5)}catch(e){}}
function speak(t){if("speechSynthesis" in window)speechSynthesis.speak(new SpeechSynthesisUtterance(t))}
function addTimer(){const s=STEPS[cur];if(!s.m)return;timers.push({id:++tid,label:`Step ${cur+1}`,end:Date.now()+s.m*60000,ring:false});speak(`${s.m} minute timer started`);drawTimers()}
$("tbtn").onclick=addTimer;
function fmt(ms){ms=Math.max(0,ms);const t=Math.ceil(ms/1000);return`${Math.floor(t/60)}:${String(t%60).padStart(2,"0")}`}
function drawTimers(){
  $("timers").innerHTML=timers.map(t=>`<div class="tm ${t.ring?'ring':''}"><span>${t.label}</span><span class="c">${t.ring?"Done!":fmt(t.end-Date.now())}</span><button data-a="add" data-id="${t.id}">+1m</button><button data-a="x" data-id="${t.id}">✕</button></div>`).join("");
}
$("timers").onclick=e=>{const b=e.target.closest("button");if(!b)return;const t=timers.find(x=>x.id==b.dataset.id);
  if(b.dataset.a=="x")timers=timers.filter(x=>x!=t);else{if(t.ring){t.ring=false;t.end=Date.now()}t.end+=60000}drawTimers()};
setInterval(()=>{timers.forEach(t=>{if(!t.ring&&t.end<=Date.now()){t.ring=true;speak(`${t.label} timer is done`)}if(t.ring)beep()});if(timers.length)drawTimers()},1000);
// Hands-free voice
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;let rec,listening=false;
$("mic").onclick=()=>{
  if(!SR){$("mic").textContent="🎤 Not supported";return}
  if(!rec){rec=new SR();rec.continuous=true;rec.lang="en-US";
    rec.onresult=e=>{const w=e.results[e.results.length-1][0].transcript.toLowerCase();
      if(/next|forward/.test(w))go(1);else if(/back|previous/.test(w))go(-1);
      else if(/timer|start/.test(w))addTimer();
      else if(/stop|dismiss/.test(w)){timers=timers.filter(t=>!t.ring);drawTimers()}
      else if(/repeat|read/.test(w))speak($("txt").textContent)};
    rec.onend=()=>{if(listening)rec.start()}}
  listening=!listening;listening?rec.start():rec.stop();
  $("mic").classList.toggle("on",listening);$("mic").textContent=listening?"🎤 Listening":"🎤 Voice off";
};
document.onkeydown=e=>{if(e.key=="ArrowRight"||e.key==" ")go(1);if(e.key=="ArrowLeft")go(-1)};
if(navigator.wakeLock)navigator.wakeLock.request("screen").catch(()=>{});
render();renderIng();
</script>
</body>
</html>
